int solution(int X, const int *A, int n) {
    static char seen[2 * OFFSET + 1];
    memset(seen, 0, sizeof(seen));
    int distinct = 0;
    for (int i = 0; i < n; i++) {
        if (A[i] <= X && !seen[A[i] + OFFSET]) {
